'use client';
import { useEffect, useState } from 'react';
import { supabaseClient } from '@/lib/supabaseClient';
import { useRouter, useParams } from 'next/navigation';
import toast from 'react-hot-toast';
import Loader from '@/components/Loader';

export default function CoachEditor() {
  const { id } = useParams();
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  
  // Form State
  const [name, setName] = useState('');
  const [role, setRole] = useState('head_coach');
  const [teamSlug, setTeamSlug] = useState('senior-men');
  const [displayOrder, setDisplayOrder] = useState(1);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState('');

  useEffect(() => {
    if (id !== 'new') {
      fetch(`http://localhost:5001/api/coaches/${id}`)
        .then(res => res.json())
        .then(data => {
          setName(data.name);
          setRole(data.role);
          setTeamSlug(data.team_slug);
          setDisplayOrder(data.display_order);
          setPreviewUrl(data.image_url);
        });
    }
  }, [id]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      let finalImageUrl = previewUrl;

      // 1. Upload Image to Supabase Storage if a new file is selected
      if (imageFile) {
        const fileExt = imageFile.name.split('.').pop();
        const fileName = `${Date.now()}.${fileExt}`;
        const filePath = `staff/${fileName}`;

        const { error: uploadError } = await supabaseClient.storage
          .from('coach-photos')
          .upload(filePath, imageFile);

        if (uploadError) throw uploadError;

        const { data } = supabaseClient.storage.from('coach-photos').getPublicUrl(filePath);
        finalImageUrl = data.publicUrl;
      }

      // 2. Submit to your Express Backend
      const method = id === 'new' ? 'POST' : 'PUT';
      const url = id === 'new' ? `http://localhost:5001/api/coaches` : `http://localhost:5001/api/coaches/${id}`;

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name, role, team_slug: teamSlug, image_url: finalImageUrl, display_order: displayOrder
        }),
      });

      if (!res.ok) throw new Error('Failed to save to database');

      toast.success('Coach saved successfully!');
      router.push('/admin/coaches');
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#020617] text-white flex items-center justify-center p-6">
      <div className="max-w-md w-full">
        <div className="mb-10 text-center">
          <h1 className="text-3xl font-black uppercase italic">Coach <span className="text-red-600">Editor</span></h1>
        </div>

        <form onSubmit={handleSave} className="bg-slate-900/50 border border-slate-800 p-8 rounded-[2.5rem] space-y-6">
          {/* Image Upload */}
          <div className="flex flex-col items-center gap-4">
            <div className="relative w-24 h-24 group border-2 border-slate-800 rounded-full overflow-hidden">
              <img src={imageFile ? URL.createObjectURL(imageFile) : (previewUrl || '/placeholder-coach.png')} className="w-full h-full object-cover" />
              <label className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 cursor-pointer text-[10px] font-black uppercase">
                Upload <input type="file" className="hidden" onChange={(e) => setImageFile(e.target.files?.[0] || null)} />
              </label>
            </div>
          </div>

          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-2">Full Name</label>
              <input value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-sm outline-none focus:border-red-600" placeholder="Coach Name" />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-2">Team</label>
                <select value={teamSlug} onChange={e => setTeamSlug(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-sm outline-none">
                  <option value="senior-men">Senior Men</option>
                  <option value="reserve-men">Reserve Men</option>
                  <option value="senior-women">Senior Women</option>
                  <option value="reserve-women">Reserve Women</option>
                  <option value="juniors">Juniors</option>
                </select>
              </div>
              <div>
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-2">Role</label>
                <select value={role} onChange={e => setRole(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-sm outline-none">
                  <option value="head_coach">Head Coach</option>
                  <option value="assistant_coach">Assistant Coach</option>
                </select>
              </div>
            </div>
          </div>

          <button disabled={loading} className="w-full bg-red-600 py-4 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-red-700 transition-all">
            {loading ? <Loader /> : 'Save Coach'}
          </button>
        </form>
      </div>
    </div>
  );
}